                      "format": "无生",
                      "designVersion": "d1",
                      "boardImage": "/lessons/g10-required-1-u04-p03/rehearsals/r2_blackboard.jpg",
                      "video": "https://www.bilibili.com/video/BV1XYpG6mESS/"
